import 'package:flutter/material.dart';import '../../../core/data/astro_repository.dart';import '../../../core/models/zodiac_sign.dart';import '../../../core/theme/app_theme.dart';import '../../../features/journal/presentation/journal_screen.dart';import '../../../shared/widgets/app_components.dart';
class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen> createState()=>_SearchScreenState();}
class _SearchScreenState extends State<SearchScreen>{String query='';List<Map<String,Object?>> saved=[],journal=[];Future<void> _search(String v)async{query=v;saved=await AstroRepository.instance.saved();journal=await AstroRepository.instance.journal(query:v);if(mounted)setState((){});}
@override Widget build(BuildContext context){final signs=zodiacSigns.where((s)=>query.isNotEmpty&&[s.name,s.element,s.modality,s.about].join(' ').toLowerCase().contains(query.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:const Text('Search AstroDaily')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Find something to explore'),TextField(onChanged:_search,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search signs, saved readings and journal')),const SizedBox(height:14),for(final s in signs)ListTile(leading:Text(s.glyph,style:const TextStyle(fontSize:24,color:AppTheme.primary)),title:Text(s.name),subtitle:Text(s.element+' · '+s.modality)),for(final r in saved.where((r)=>[r['title'],r['body']].join(' ').toLowerCase().contains(query.toLowerCase())))ListTile(leading:const Icon(Icons.bookmark_outline),title:Text(r['title'] as String? ?? ''),subtitle:const Text('Saved reading')),for(final j in journal)ListTile(leading:const Icon(Icons.lock_outline),title:Text(j['day'] as String),subtitle:Text(j['body'] as String,maxLines:1),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>JournalScreen(prompt:j['prompt'] as String,entry:j)))),if(query.isNotEmpty&&signs.isEmpty&&saved.isEmpty&&journal.isEmpty)const InfoCard('No matching cached content found.') ]));}
}
